def get(url, tries=8, minsize=0):
    for k in range(tries):
        try:
            with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=180) as r:
                b = r.read()
            if len(b) >= minsize and not b[:200].lstrip().lower().startswith((b"<!doctype", b"<html")) or minsize == 0:
                return b
        except Exception as e:
            print("retry", k, url, e, flush=True)
        time.sleep(min(5 * 2 ** k, 120))
    raise RuntimeError(url)


def listing(url, pat):
    return sorted(set(re.findall(pat, get(url).decode("latin1"))))

